// Merge session + intent + original input into one object for downstream routing
const original = $('When Executed by Another Workflow').first().json;
const session = $('Load Session').first().json;
const intent = $input.first().json;

return [{
  json: {
    // Original input
    phone: original.phone,
    display_name: original.display_name || session.display_name,
    message_text: original.message_text,
    message_type: original.message_type,
    received_at: original.received_at,
    // Session data
    session_status: session.session_status,
    short_memory: session.short_memory,
    last_intent: session.last_intent,
    last_user_message: session.last_user_message,
    last_bot_message: session.last_bot_message,
    last_seen_at: session.last_seen_at,
    message_count: session.message_count,
    needs_human: session.needs_human,
    is_new_session: session.is_new_session,
    is_stale_session: session.is_stale_session,
    // Intent data
    intent: intent.intent,
    confidence: intent.confidence,
    intent_reason: intent.reason
  }
}];

const original = $('Merge Context').item ? $('Merge Context').first().json : $('When Executed by Another Workflow').first().json;
const response = $input.first().json;

const intent = original.intent || response.intent || 'unknown';
const needs_human = intent === 'human_handoff' ? true : (original.needs_human || false);

// Build save session payload
const savePayload = {
  phone: original.phone,
  display_name: original.display_name,
  session_status: 'active',
  short_memory: response.updated_short_memory || '',
  last_intent: intent,
  last_user_message: original.message_text,
  last_bot_message: response.response_text,
  needs_human: needs_human
};

// Build log payload
const logPayload = {
  timestamp: new Date().toISOString(),
  phone: original.phone,
  display_name: original.display_name,
  incoming_message: original.message_text,
  intent: intent,
  response_sent: response.response_text,
  kb_hit: response.kb_hit || false,
  failed: false,
  failure_reason: ''
};

// Final output
return [{
  json: {
    response_text: response.response_text,
    intent: intent,
    kb_hit: response.kb_hit || false,
    updated_short_memory: response.updated_short_memory || '',
    needs_human: needs_human,
    status: 'ok',
    phone: original.phone,
    display_name: original.display_name,
    message_text: original.message_text,
    message_type: original.message_type || 'text',
    received_at: original.received_at,
    _save_payload: savePayload,
    _log_payload: logPayload
  }
}];

// Non-text path: build log payload and return
const original = $('When Executed by Another Workflow').first().json;
const logPayload = {
  timestamp: new Date().toISOString(),
  phone: original.phone,
  display_name: original.display_name,
  incoming_message: '[non-text: ' + original.message_type + ']',
  intent: 'unsupported',
  response_sent: 'Por ahora solo puedo ayudarte con mensajes de texto.',
  kb_hit: false,
  failed: false,
  failure_reason: ''
};

return [{
  json: {
    response_text: 'Por ahora solo puedo ayudarte con mensajes de texto.',
    intent: 'unsupported',
    kb_hit: false,
    updated_short_memory: 'Envió contenido no soportado (no texto)',
    needs_human: false,
    status: 'ok',
    _log_payload: logPayload
  }
}];
